CREATE POLICY "Admins upload reward images (avatars)" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'rewards' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update reward images (avatars)" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'rewards' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete reward images (avatars)" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'rewards' AND public.has_role(auth.uid(), 'admin'));